"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[41103],{3331:(e,i,a)=>{a.d(i,{R:()=>t,x:()=>s});var o=a(36672);const n={},r=o.createContext(n);function t(e){const i=o.useContext(r);return o.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function s(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:t(e.components),o.createElement(r.Provider,{value:i},e.children)}},95914:(e,i,a)=>{a.r(i),a.d(i,{assets:()=>c,contentTitle:()=>s,default:()=>z,frontMatter:()=>t,metadata:()=>o,toc:()=>w});const o=JSON.parse('{"id":"2023/04/17","title":"2023-04-17","description":"De-Stressing Booking.com","source":"@site/i18n/pl/docusaurus-plugin-content-docs/current/2023/04/17.md","sourceDirName":"2023/04","slug":"/2023/04/17","permalink":"/pl/2023/04/17","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/pl/docusaurus-plugin-content-docs//current/2023/04/17.md","tags":[],"version":"current","frontMatter":{"localized_date":"17 kwietnia 2023","top_news":"De-Stressing Booking.com"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-18","permalink":"/pl/2023/04/18"},"next":{"title":"2023-04-16","permalink":"/pl/2023/04/16"}}');var n=a(23420),r=a(3331);const t={localized_date:"17 kwietnia 2023",top_news:"De-Stressing Booking.com"},s="2023-04-17",c={},w=[{value:"De-Stressing Booking.com",id:"de-stressing-bookingcom",level:2},{value:"U\u017cy\u0142em Stable Diffusion i Dreambooth, aby stworzy\u0107 portret artystyczny mojego psa",id:"u\u017cy\u0142em-stable-diffusion-i-dreambooth-aby-stworzy\u0107-portret-artystyczny-mojego-psa",level:2},{value:"AT&amp;T Wireless traffic shaping najwyra\u017aniej czyni niekt\xf3re strony internetowe nieu\u017cytecznymi",id:"att-wireless-traffic-shaping-najwyra\u017aniej-czyni-niekt\xf3re-strony-internetowe-nieu\u017cytecznymi",level:2},{value:"Future Blues - strona Emily o Cowboy Bebop (1999)",id:"future-blues---strona-emily-o-cowboy-bebop-1999",level:2},{value:"Zmywarka do naczy\u0144 \u0141oso\u015b",id:"zmywarka-do-naczy\u0144-\u0142oso\u015b",level:2},{value:"Pico3D: Open World 3D Game Engine for the PicoSystem (RP2040 Microcontroller)",id:"pico3d-open-world-3d-game-engine-for-the-picosystem-rp2040-microcontroller",level:2},{value:"Wayback: Samodzielna us\u0142uga archiwizacji zintegrowana z Internet Archive",id:"wayback-samodzielna-us\u0142uga-archiwizacji-zintegrowana-z-internet-archive",level:2},{value:"Najszybsza biblioteka do sk\u0142adu matematycznego w sieci",id:"najszybsza-biblioteka-do-sk\u0142adu-matematycznego-w-sieci",level:2},{value:"&#39;Algebra for none&#39; zawodzi w San Francisco",id:"algebra-for-none-zawodzi-w-san-francisco",level:2},{value:"FSF krytykuje Google za usuni\u0119cie JPEG-XL w Chrome",id:"fsf-krytykuje-google-za-usuni\u0119cie-jpeg-xl-w-chrome",level:2}];function y(e){const i={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(i.header,{children:(0,n.jsx)(i.h1,{id:"2023-04-17",children:"2023-04-17"})}),"\n",(0,n.jsx)(i.h2,{id:"de-stressing-bookingcom",children:"De-Stressing Booking.com"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.alexcharlton.co/projects/booking-com-de-stresser",children:"Original"}),'.\nPisarz dzieli si\u0119 opini\u0105 na temat nadu\u017cywania taktyk perswazji na stronach e-commerce, a konkretnie Booking.com, i wprowadza ich Chrome Extension, "De-stresser", kt\xf3ry usuwa stresuj\u0105ce wiadomo\u015bci i powiadomienia z Booking.com, daj\u0105c u\u017cytkownikom bardziej przyjemne do\u015bwiadczenie. Poprzez ukrycie tag\xf3w perswazji i dostosowanie j\u0119zyka do brzmienia bardziej pozytywne, De-stresser umo\u017cliwia spokojniejsze i bardziej relaksuj\u0105ce do\u015bwiadczenie rezerwacji dla u\u017cytkownik\xf3w. Rozszerzenie jest ju\u017c na \u017cywo i dost\u0119pne do u\u017cytku na Booking.com.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35590734",children:"Discussion Service"}),'.\nBooking.com spotyka si\u0119 z krytyk\u0105 dotycz\u0105c\u0105 stosowania taktyk sprzeda\u017cy pod du\u017c\u0105 presj\u0105, w tym komunikat\xf3w o pilno\u015bci i wyskakuj\u0105cych okienkach, kt\xf3re mog\u0105 odstrasza\u0107 u\u017cytkownik\xf3w. Krytycy twierdz\u0105, \u017ce to podej\u015bcie priorytetem kr\xf3tkoterminowe metryki nad d\u0142ugoterminowej lojalno\u015bci klienta. U\u017cytkownicy donosz\u0105, \u017ce znale\u017ali sposoby na obej\u015bcie tych taktyk, w tym u\u017cycie rozszerze\u0144 do ich blokowania lub filtrowania. Tymczasem u\u017cytkownicy Discussion Service debatuj\u0105 nad zaletami test\xf3w A/B, niekt\xf3rzy wskazuj\u0105 na ich potencja\u0142 do tworzenia "ciemnych wzorc\xf3w" na stronach internetowych. Pomimo tych obaw, wielu u\u017cytkownik\xf3w nadal korzysta\u0107 z agregator\xf3w rezerwacji jak Booking.com i Expedia, albo dla wygody lub dlatego, \u017ce oferuj\u0105 korzystne ceny i polityki anulowania. Niekt\xf3rzy eksperci ostrzegaj\u0105, \u017ce rezerwacja bezpo\u015brednio z hoteli mo\u017ce zaoferowa\u0107 lepsze opcje rozwi\u0105zywania spor\xf3w, podczas gdy inni wskazuj\u0105, \u017ce stawki prowizji dla stron rezerwacyjnych mog\u0105 si\u0119 znacznie r\xf3\u017cni\u0107 w zale\u017cno\u015bci od hotelu. Niemniej jednak, programy lojalno\u015bciowe hoteli mog\u0105 zapewni\u0107 znacz\u0105ce korzy\u015bci dla os\xf3b cz\u0119sto podr\xf3\u017cuj\u0105cych.']}),"\n",(0,n.jsx)(i.h2,{id:"u\u017cy\u0142em-stable-diffusion-i-dreambooth-aby-stworzy\u0107-portret-artystyczny-mojego-psa",children:"U\u017cy\u0142em Stable Diffusion i Dreambooth, aby stworzy\u0107 portret artystyczny mojego psa"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.shruggingface.com/blog/how-i-used-stable-diffusion-and-dreambooth-to-create-a-painted-portrait-of-my-dog",children:"Original"}),".\nArtyku\u0142 omawia wykorzystanie technik Stable Diffusion i Dreambooth AI do stworzenia wysokiej jako\u015bci malowanego portretu psa. Autor dzieli si\u0119 ca\u0142ym swoim workflow i podaje szczeg\xf3\u0142owe instrukcje, jak trenowa\u0107 model Dreambooth na zdj\u0119ciach swojego psa. Artyku\u0142 omawia r\xf3wnie\u017c wykorzystanie skalowania do powi\u0119kszania ma\u0142ych obraz\xf3w w celu uzyskania wysokiej jako\u015bci odbitek oraz przedstawia Stable Diffusion jako prze\u0142om w \u015bwiecie sztuki generowania tekstu na obraz."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35592847",children:"Discussion Service"}),".\nU\u017cytkownik Discussion Service wykorzysta\u0142 Stable Diffusion i Dreambooth do stworzenia artystycznego portretu swojego psa, a w komentarzach dyskutowano na temat sprzeciwu wobec sztuki AI oraz debat na temat praw autorskich i uczciwego wykorzystania. Wykorzystanie generatywnej SI w sztuce wi\u0105\u017ce si\u0119 z kwestiami etycznymi dotycz\u0105cymi prawa autorskiego i uczciwego wykorzystania, a opinie na ten temat s\u0105 podzielone. Niekt\xf3rzy krytykowali Stable Diffusion za wykorzystanie bez wynagrodzenia skradzionych dzie\u0142 sztuki jako danych szkoleniowych, podczas gdy inni chwalili technologi\u0119 i jej potencja\u0142 dla dalszych innowacji w tej dziedzinie."]}),"\n",(0,n.jsx)(i.h2,{id:"att-wireless-traffic-shaping-najwyra\u017aniej-czyni-niekt\xf3re-strony-internetowe-nieu\u017cytecznymi",children:"AT&T Wireless traffic shaping najwyra\u017aniej czyni niekt\xf3re strony internetowe nieu\u017cytecznymi"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://adriano.fyi/post/2023/2023-04-16-att-traffic-shaping-makes-websites-unusable/",children:"Original"}),'.\n"Nieograniczony" plan 100Mbit firmy AT&T z 50GB na priorytetowe dane mo\u017ce agresywnie kszta\u0142towa\u0107 ruch, powoduj\u0105c, \u017ce niekt\xf3re strony internetowe s\u0105 nieu\u017cyteczne, podczas gdy test wykaza\u0142, \u017ce karta SIM Verizon nie mia\u0142a tego samego problemu. Ruch Akamai wykazuje dowody na celowe manipulowanie strumieniem TCP. Kszta\u0142towanie ruchu dotyczy tylko kont z dost\u0119pem do danych na kontach biznesowych.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35592607",children:"Discussion Service"}),".\nAT&T Wireless podobno d\u0142awi adresy IP dla niekt\xf3rych witryn strumieniowych wideo, co sprawia, \u017ce niekt\xf3re strony internetowe s\u0105 bezu\u017cyteczne i powoduje rozbie\u017cno\u015bci w testach pr\u0119dko\u015bci Internetu. U\u017cytkownicy zaproponowali rozwi\u0105zania, takie jak z\u0142o\u017cenie skargi FCC, przy u\u017cyciu VPN, aby omin\u0105\u0107 d\u0142awienie, lub pr\xf3buje inny APN. Niekt\xf3rzy komentatorzy s\u0105 sceptyczni co do z\u0142ych intencji za d\u0142awieniem, podczas gdy inni proponuj\u0105 rozwi\u0105zania takie jak limity stawek lub obni\u017cenie jako\u015bci wideo, aby zachowa\u0107 przydzia\u0142 danych."]}),"\n",(0,n.jsx)(i.h2,{id:"future-blues---strona-emily-o-cowboy-bebop-1999",children:"Future Blues - strona Emily o Cowboy Bebop (1999)"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://futureblues.com/",children:"Orygina\u0142"}),".\nPrzepraszam, nie ma tekstu dostarczonego dla mnie do streszczenia."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35589124",children:"Discussion Service"}),".\nU\u017cytkownicy Discussion Service wyra\u017caj\u0105 nostalgi\u0119 za oryginalnymi i kreatywnymi projektami klasycznych stron internetowych, kontrastuj\u0105c je ze standardow\u0105, ha\u0142a\u015bliw\u0105 i zmonetyzowan\u0105 natur\u0105 wsp\xf3\u0142czesnych stron, sugeruj\u0105c t\u0119sknot\u0119 za bardziej artystycznymi, skupionymi na indywidualno\u015bci krajobrazami medialnymi. Pojawiaj\u0105 si\u0119 punkty dyskusyjne por\xf3wnuj\u0105ce Wikipedi\u0119 i Fandom, oraz rozr\xf3\u017cnienie mi\u0119dzy stronami mobilnymi a tymi przeznaczonymi tylko dla komputer\xf3w stacjonarnych, a projekt strony internetowej budzi zar\xf3wno nostalgi\u0119, jak i zdumienie z powodu swojej d\u0142ugowieczno\u015bci. Og\xf3lnie rzecz bior\u0105c, post oferuje wgl\u0105d w mi\u0142e wspomnienia u\u017cytkownik\xf3w z pocz\u0105tk\xf3w internetu i stanowi platform\u0119 do dyskusji o obecnym stanie sieci."]}),"\n",(0,n.jsx)(i.h2,{id:"zmywarka-do-naczy\u0144-\u0142oso\u015b",children:"Zmywarka do naczy\u0144 \u0141oso\u015b"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://en.wikipedia.org/wiki/Dishwasher_salmon",children:"Original"}),".\n\u0141oso\u015b do zmywarki to danie rybne wykonane przez zawini\u0119cie kawa\u0142k\xf3w \u0142ososia w co najmniej dwie warstwy folii aluminiowej i umieszczenie go w zmywarce podczas cyklu mycia i suszenia. Metoda ta zosta\u0142a po raz pierwszy zademonstrowana w USA przez Vincenta Price'a w 1975 roku i od tego czasu pojawia\u0142a si\u0119 w r\xf3\u017cnych mediach. Istniej\u0105 jednak obawy dotycz\u0105ce sp\xf3jno\u015bci temperatur w zmywarkach, co mo\u017ce prowadzi\u0107 do niepe\u0142nego ugotowania i potencjalnych zagro\u017ce\u0144 dla zdrowia."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35586683",children:"Discussion Service"}),".\nArtyku\u0142 Hacker News o gotowaniu \u0142ososia w zmywarce wywo\u0142uje debat\u0119 na temat bezpiecze\u0144stwa tej metody gotowania, a u\u017cytkownicy z bran\u017cy bezpiecze\u0144stwa \u017cywno\u015bci odpieraj\u0105 twierdzenia zawarte w \u015bledztwie YouTubera. Podczas gdy bezpiecze\u0144stwo gotowania w zmywarce zale\u017cy od wielu czynnik\xf3w, do zabicia bakterii w \u0142ososiu wymagane jest co najmniej 63\xb0C przez 15 sekund."]}),"\n",(0,n.jsx)(i.h2,{id:"pico3d-open-world-3d-game-engine-for-the-picosystem-rp2040-microcontroller",children:"Pico3D: Open World 3D Game Engine for the PicoSystem (RP2040 Microcontroller)"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://github.com/bernhardstrobl/Pico3D",children:"Orygina\u0142"}),".\nSilnik gry Pico3D wykorzystuje drugi rdze\u0144 RP2040 jako dedykowany rasteryzator/GPU do uruchomienia kompletnej gry 3D z otwartym \u015bwiatem na mikrokontrolerze za 1$. Silnik zawiera ma\u0142e miasto i przedmie\u015bcia, w kt\xf3rych mo\u017cna strzela\u0107 do zombie, z dost\u0119pnymi samouczkami Blendera do tworzenia \u015bwiat\xf3w gry. Symulacja silnika obejmuje obecnie 50 postaci niezale\u017cnych i 50 zombie jednocze\u015bnie, z renderowaniem zoptymalizowanym za pomoc\u0105 odleg\u0142o\u015bci i usuwania frustum widoku."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35589172",children:"Discussion Service"}),".\nNowy silnik gier 3D o nazwie Pico3D zosta\u0142 opracowany dla mikrokontrolera RP2040 z wy\u015bwietlaczem 120x120px, brakuje mu wystarczaj\u0105cej ilo\u015bci pami\u0119ci i pami\u0119ci wideo RAM, ale ma zunifikowane API. Hakerzy s\u0105 entuzjastycznie nastawieni do kreatywnych sposob\xf3w wykorzystania Pico/RP2040, a unikalne zastosowanie uk\u0142ad\xf3w RAM w buforze ramki sprawia, \u017ce ten artyku\u0142 wyr\xf3\u017cnia si\u0119 na stronie tech."]}),"\n",(0,n.jsx)(i.h2,{id:"wayback-samodzielna-us\u0142uga-archiwizacji-zintegrowana-z-internet-archive",children:"Wayback: Samodzielna us\u0142uga archiwizacji zintegrowana z Internet Archive"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://github.com/wabarc/wayback",children:"Original"}),".\nWayback to samoobs\u0142ugowe narz\u0119dzie archiwizacyjne, kt\xf3rego celem jest migawka stron internetowych w kapsu\u0142ach czasu. Jest darmowe, open-source, wieloplatformowe i pozwala na \u0142atwiejsz\u0105 integracj\u0119 z r\xf3\u017cnymi platformami, w tym Internet Archive, archive.today, IPFS i Telegraph. Zapewnia r\xf3wnie\u017c kilka opcji instalacji, w tym przez GitHub, Snapcraft, APT, RPM i Homebrew."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35586845",children:"Discussion Service"}),'.\nSamowystarczalna us\u0142uga archiwizacji Wabarc migawki stron internetowych w "kapsu\u0142y czasu" i przechowuje pliki do u\u017cytku offline; u\u017cytkownicy Discussion Service krytykuj\u0105 jednak niejasne README i brak dokumentacji. Inne podobne projekty obejmuj\u0105 ArchiveBox, Shiori, DiskerNet i SingleFile; HTTrack Website Copier jest zalecany do pobierania ca\u0142ej strony internetowej lokalnie, podczas gdy Browsertrix/Brozzler crawls z headless przegl\u0105darek dla dok\u0142adno\u015bci. U\u017cytkownik Discussion Service poleca The Old Net do przegl\u0105dania starych/nowoczesnych przegl\u0105darek bez JS, a podlinkowane repo wymaga wi\u0119kszej jasno\u015bci co do mo\u017cliwo\u015bci udost\u0119pniania i ustalonych standard\xf3w archiwizacji.']}),"\n",(0,n.jsx)(i.h2,{id:"najszybsza-biblioteka-do-sk\u0142adu-matematycznego-w-sieci",children:"Najszybsza biblioteka do sk\u0142adu matematycznego w sieci"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://katex.org/",children:"Original"}),".\nKaTeX jest szybk\u0105 bibliotek\u0105 sk\u0142adu matematycznego dla sieci, kt\xf3ra oferuje uk\u0142ad o jako\u015bci druku oparty na TeX Donalda Knutha, nie ma \u017cadnych zale\u017cno\u015bci i mo\u017ce by\u0107 \u0142atwo do\u0142\u0105czona do zasob\xf3w strony internetowej w celu renderowania po stronie serwera za pomoc\u0105 Node.js. Jej proste API wydajnie renderuje wyra\u017cenia matematyczne, nawet na stronach zawieraj\u0105cych wiele wyra\u017ce\u0144, bez ogranicze\u0144 zwi\u0105zanych z przegl\u0105dark\u0105 lub \u015brodowiskiem, a ponadto jest otwarta na licencji MIT."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35588985",children:"Discussion Service"}),".\nKaTeX, najszybsza biblioteka do sk\u0142adu matematycznego w sieci, nie obs\u0142uguje wykres\xf3w, co czyni j\u0105 nieodpowiedni\u0105 dla niekt\xf3rych matematyk\xf3w, podczas gdy MathJax i AsciiMath maj\u0105 podobne projekty. Strona por\xf3wnawcza zosta\u0142a udost\u0119pniona, a wydajno\u015b\u0107 i praktyczno\u015b\u0107 dostosowywania znacznik\xf3w do r\xf3\u017cnych kontekst\xf3w jest przedmiotem debaty u\u017cytkownik\xf3w Hacker News."]}),"\n",(0,n.jsx)(i.h2,{id:"algebra-for-none-zawodzi-w-san-francisco",children:"'Algebra for none' zawodzi w San Francisco"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.joannejacobs.com/post/algebra-for-none-fails-in-san-francisco",children:"Original"}),'.\nSan Francisco Unified dystrykt szkolny "Algebra dla nikogo" polityka nie uda\u0142o si\u0119 poprawi\u0107 osi\u0105gni\u0119cia czarnych i latynoskich uczni\xf3w w zaawansowanych matematyki, wed\u0142ug badania przez profesor\xf3w Stanford, co spowodowa\u0142o wzrost luki w osi\u0105gni\u0119ciach. Decyzja o op\xf3\u017anieniu algebry do dziewi\u0105tej klasy i umieszczeniu uczni\xf3w o niskich i wysokich osi\u0105gni\u0119ciach w tych samych klasach nie pomog\u0142a uczniom o niskich wynikach i utrudni\u0142a sukces uczniom o wysokich wynikach. Rodziny, kt\xf3re mog\u0105 sobie na to pozwoli\u0107, zwr\xf3ci\u0142y si\u0119 w stron\u0119 kurs\xf3w online lub szk\xf3\u0142 prywatnych. Grupa rodzic\xf3w z\u0142o\u017cy\u0142a pozew przeciwko dystryktowi, twierdz\u0105c, \u017ce narusza on prawo stanowe dotycz\u0105ce sprawiedliwego dost\u0119pu do zaawansowanej matematyki.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35595026",children:"Discussion Service"}),".\nPolityka San Francisco polegaj\u0105ca na op\xf3\u017anianiu algebry do 9 klasy i umieszczaniu uczni\xf3w o niskich, \u015brednich i wysokich wynikach w tych samych klasach zosta\u0142a skrytykowana, przy czym niekt\xf3rzy sugeruj\u0105, \u017ce podstawowe poj\u0119cia matematyczne powinny by\u0107 nauczane wcze\u015bniej. Niekt\xf3rzy u\u017cytkownicy Discussion Service sugeruj\u0105, by motywowa\u0107 do osi\u0105gania sukces\xf3w w nauce i zaj\u0119ciach pozaszkolnych poprzez powi\u0105zanie ich z nagrodami finansowymi, podczas gdy inni twierdz\u0105, \u017ce lepszym rozwi\u0105zaniem by\u0142oby subsydiowanie szkolnictwa wy\u017cszego poprzez systemy kredytowe, dzi\u0119ki kt\xf3rym za studia mo\u017cna zap\u0142aci\u0107 p\xf3\u017aniej. Trwaj\u0105 debaty na temat przydatno\u015bci tradycyjnej edukacji matematycznej i skuteczno\u015bci zwi\u0119kszenia finansowania w celu zmniejszenia wielko\u015bci klas, przy czym niekt\xf3rzy u\u017cytkownicy sugeruj\u0105 nauczanie matematyki poprzez problemy in\u017cynierskie i korzy\u015bci p\u0142yn\u0105ce z edukacji online."]}),"\n",(0,n.jsx)(i.h2,{id:"fsf-krytykuje-google-za-usuni\u0119cie-jpeg-xl-w-chrome",children:"FSF krytykuje Google za usuni\u0119cie JPEG-XL w Chrome"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.phoronix.com/news/FSF-Slams-Google-JPEG-XL",children:"Original"}),'.\nFree Software Foundation krytykuje decyzj\u0119 Google o porzuceniu obs\u0142ugi JPEG-XL w Chrome, podkre\u015blaj\u0105c potrzeb\u0119 wyboru przegl\u0105darki i wolnych format\xf3w medi\xf3w. Pomimo wrzawy spo\u0142eczno\u015bci, in\u017cynierowie Google nadal kontynuowali t\u0119 decyzj\u0119, kt\xf3ra pozostaje jedn\u0105 z najbardziej "gwiazdkowych" spraw w historii projektu Chromium. U\u017cytkownicy okazali silne wsparcie dla JPEG-XL, ale wydaje si\u0119, \u017ce koncentracja Google na kontroli nad wolno\u015bci\u0105 zwyci\u0119\u017cy\u0142a.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35589179",children:"Discussion Service"}),".\nGoogle spotyka si\u0119 z krytyk\u0105 ze strony Free Software Foundation za zaprzestanie obs\u0142ugi JPEG-XL w Chrome pomimo jego przyj\u0119cia przez g\u0142\xf3wne edytory obraz\xf3w. Niekt\xf3rzy u\u017cytkownicy twierdz\u0105, \u017ce starsze formaty, takie jak PNG i JPEG, s\u0105 wystarczaj\u0105ce, podczas gdy inni wol\u0105 kodeki takie jak AVIF dla wideo. Debata toczy si\u0119 wok\xf3\u0142 rentowno\u015bci i przyj\u0119cia nowych format\xf3w obrazu w ekosystemie, przy czym odnotowano wsparcie przemys\u0142u i zainteresowanie JPEG-XL, ale przyj\u0119cie zale\u017cy od tego, czy wszystkie g\u0142\xf3wne przegl\u0105darki b\u0119d\u0105 go wspiera\u0107."]})]})}function z(e={}){const{wrapper:i}={...(0,r.R)(),...e.components};return i?(0,n.jsx)(i,{...e,children:(0,n.jsx)(y,{...e})}):y(e)}}}]);